import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"13、【同人】 离下乾上","description":"周易口诀义 - 13、【同人】 离下乾上","frontmatter":{"title":"13、【同人】 离下乾上","description":"周易口诀义 - 13、【同人】 离下乾上"},"headers":[],"relativePath":"zh/classics/koujueyi/015.md","filePath":"zh/classics/koujueyi/015.md"}'),r={name:"zh/classics/koujueyi/015.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_13、【同人】-离下乾上" tabindex="-1">13、【同人】 离下乾上 <a class="header-anchor" href="#_13、【同人】-离下乾上" aria-label="Permalink to “13、【同人】 离下乾上”">​</a></h1><p>彖曰：同人，柔得位得中而应乎乾曰「同人」。同人曰</p><p>「同人于野，亨，利涉大川」，乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。</p><p>象曰：天与火，同人。君子以类族辨物。</p><p>初九，同人于门，无咎。</p><p>象曰：出门同人，又谁咎也。</p><p>六二：同人于宗，吝。</p><p>象曰：「同人于宗」，吝道也。</p><p>九三：伏戎于莽，升其高陵，三岁不兴。</p><p>象曰：「伏戎于莽」，敌刚也。「三岁不兴」，安行也。</p><p>九四：乘其墉，弗克攻，吉。</p><p>象曰：「乘其墉」，义弗克也。其吉则困而反则也。</p><p>九五，同人先号啕而后笑，大师克相遇。</p><p>象曰：同人之先，以中直也。大师相遇，言相克也。</p><p>上九，同人于郊，无悔。</p><p>象曰：「同人于郊」，志未得也。</p><p>解读</p><p>「同人于野，亨」者，同人者谓和同于人，故曰「同人」也。既与人同，若不广远，即不能弘博矣；野者，旷野之所，喻其与人相同，必须广远，无所不通，故曰</p><p>「同人于野，亨」也。利涉大川，利君子贞者，既与人同，不忧患难，虽大川亦能济涉，故曰「利涉大川」也。与人和同，若不以正，则是同于邪妄之道，故曰「君子相同，利以为正，利君子贞」。象曰：「天与火，同人」者，天体高，火炎上，即火势上逼，以同于天，喻已之同于人也。「君子以类族辨物」者，族，聚也；辨，分也；物，事也。君子以类而聚，君子小人，如有所同，又须分辨事物，各处其道也。</p><p>「初九，同人于门，无咎」者，初九志既弘广，不拒于物，出门与人同，即无人与之为咎也。</p><p>「六二，同人于宗，吝」者，六二专志在五，所与人同，其意𥚹狭，是鄙吝之道也。</p><p>「九三，伏戎于莽，升其高陵，三岁不兴」者，与二相近，而欲亲二，故盗憎其主，恶于五，所以潜隐兵戎于草莽之中，将以袭五，故曰「伏戎于莽」也。时升高陵以望前敌，故曰「升其高陵」。以九三之臣而欲拒九五之君，势不可敌也。纵三年亦不能兴起兵众以侵害于君，故曰「三岁不兴」也。</p><p>「九四：乘其墉，弗克攻，吉」者，三处下卦之极，似乘墉墙而不能克敌矣。困罢乃反，以改过修其德，乃获吉也。</p><p>九五：同人先号啕而后笑，大师克。相遇者，九五所应在二，隔于三、四，不得其应合，乃悲泣也。三四是臣而五是君，以臣拒君，力不可敌，后乃与二相遇，故「后笑」。不能以服物，而以兴举师旅乃克，以明失「同人」之德也。</p><p>上九：同人于郊，无悔者，独处于外，与人和同，在于郊境之外也。内无其应，无所陵竞，未得和同之志，但「无悔」而已。</p>',25)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
